+
+fn one_feed(from: Point3, to: Point3) -> Toolpath {
+    let moves = vec![
+        Move::new(MoveKind::Plunge, Point3::new(from.x, from.y, 5.0), from, Some(100.0)),
+        Move::new(MoveKind::Feed, from, to, Some(500.0)),
+    ];
+    Toolpath { moves, ..Toolpath::default() }
+}
